import { equipmentSetStatus, effectiveArmorFatigue } from './equipment-sets.js';
import { INJURY_BY_ID, injuryEffectText, injuryDailyMedicine } from './injuries.js';
import {hasEquipmentPerk,getContractBoardRefreshDay,canAcceptContract,getActiveContracts,getContractCategory,getInjuryCare, RETINUE_MEMBERS, hasRetinue, getScoutLevel, getBattleLootGold, getBattleChampionBounty, getBattleExperience, SETTLEMENTS, getTimeOfDay, getCompanyCart, getStashCapacity, getItem, getEquipment, getFormation, getCompanyStats, getCampSites, getLevelUp, contractObjectiveComplete, getContractTarget, PERKS, getPerkPoints, getBackground, getTraits, getTownEvent, getTownEconomy, getCaravans, getRoamingBands, getDailyFood, getCompanyTravelBonus, getMoraleEffects, shieldMaximum, getMountRewardEvents, getLootKeepQuote, getDiscoveryEvent, getRetinue, getTownServiceQuote, MAX_COMPANY_SIZE, MAX_BATTLE_SIZE, AUTO_AMMO_CAP, getReserveSlots, getBattleRoster, getSettlementAccess, getLegendaryBlacksmith } from './engine.js';
import { townFacilities } from './town-facilities.js';
import { portraitHTML, itemImage } from './portraits.js';
import { SETTLEMENT_TYPES, townAt } from './engine.js';

const esc = value => String(value ?? '').replace(/[&<>"']/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const item = getItem;
const town = id => SETTLEMENTS.find(entry => entry.id === id);
const itemIcon = (entry, alt=entry?.name) => `<img class="equipment-icon${entry?.rarity === 'famed' ? ' famed-item-icon' : ''}" src="${itemImage(entry)}" alt="${esc(alt)}">`;
export function companyHintHTML(id,label,detail){const key=`company-hint-${id}`;return `<span class="company-hint"><button type="button" class="company-hint-button" data-company-hint aria-label="About ${esc(label)}" aria-describedby="${esc(key)}" aria-expanded="false">?</button><span class="company-hint-tip" id="${esc(key)}" role="tooltip" hidden><strong>${esc(label)}</strong><span>${esc(detail)}</span></span></span>`;}
function talentHTML(person,key){const stars=person.talents?.[key]??0;return stars?` <span class="talent-stars" role="img" aria-label="${stars}-star talent" title="${stars===3?'Always +5 at level-up':`+${stars} to level-up rolls (maximum +5)`}">${'★'.repeat(stars)}</span>`:'';}
export const statLabels = {maxHp:'Hitpoints',maxFatigue:'Maximum Fatigue',resolve:'Resolve',initiative:'Initiative',meleeSkill:'Melee Skill',rangedSkill:'Ranged Skill',meleeDefense:'Melee Defense',rangedDefense:'Ranged Defense'};
const combatRoles = {auto:'Auto',frontliner:'Frontliner',skirmisher:'Skirmisher',ranged:'Ranged',flanker:'Flanker',breaker:'Breaker'};
const combatRoleHelp = {
  auto:'Auto follows current gear: melee riders on war horses with 160+ body armor become Breakers; bows, crossbows and throwing weapons keep their ranged roles.',
  frontliner:'Closes with the enemy and holds the front.',
  skirmisher:'Keeps space and pressures the nearest front line; closes when ammunition runs out.',
  ranged:'Keeps space, seeks defensive cover and picks exposed or finishing targets; closes when ammunition runs out.',
  breaker:'Charges weak points to stun and push enemies aside, then seeks exposed archers and polearms. Avoids crowded landings and Spearwall; obeys company tactics.',
  flanker:'Prefers ranged and polearm enemies, taking safe routes around their front line.',
};
const skillPreferences = {balanced:'Balanced',damage:'Damage',control:'Control'};

function combatSettingsHTML(person) {
  const role=Object.hasOwn(combatRoles,person.combatRole)?person.combatRole:'auto';
  const preference=Object.hasOwn(skillPreferences,person.skillPreference)?person.skillPreference:'balanced';
  const personId=esc(person.id);
  return `<section class="combat-settings"><h4>Battle behavior ${companyHintHTML('behavior','Battle behavior','Role guides movement and positioning. Skill preference favors balanced choices, damage or control skills. These settings do not change your formation.')}</h4><label><span>Role ${companyHintHTML('role','Battle role',combatRoleHelp[role])}</span><select data-combat-setting="combatRole" data-person-id="${personId}" aria-label="${esc(person.name)} battle role">${Object.entries(combatRoles).map(([value,label])=>`<option value="${value}"${role===value?' selected':''}>${label}</option>`).join('')}</select></label><label><span>Skill preference</span><select data-combat-setting="skillPreference" data-person-id="${personId}" aria-label="${esc(person.name)} skill preference">${Object.entries(skillPreferences).map(([value,label])=>`<option value="${value}"${preference===value?' selected':''}>${label}</option>`).join('')}</select></label></section>`;
}

export function townFacilitiesHTML(state,townId) {
  const facilities=townFacilities(state.seed,town(townId));
  return `<section class="town-facilities" aria-label="Local workshops">${facilities.length?facilities.map(f=>`<article><strong>${esc(f.name)}</strong><p>${esc(f.description)}</p></article>`).join(''):'<p>General traders carry a small rotating selection. Specialist workshops can be found in other settlements.</p>'}</section>`;
}
// Shared by the map sidebar and settlement services; affordability never hides needed care.
export function townActionsHTML(state, townId, cards=false) {
  if(townAt(state)?.id!==townId)return '';
  const actions=[['market','Marketplace','Equipment, trade goods and supplies'],['recruit','Hiring','Find brothers to fight under your banner'],['contracts','Contracts','Work for the local settlement'],['ancient-armorer','Armorer','Restore ancient armor or craft a direwolf harness']];
  if(townId==='ironford'&&getLegendaryBlacksmith(state).discovered)actions.push(['legendary-blacksmith','Legendary Blacksmith','Odran’s side quests, named merging and full transfers']);
  if(cards)actions.push(['retinue','Retinue','Company bonuses and rare finds']);
  if(getTownServiceQuote(state,'doctor').totalAmount>0||getTownServiceQuote(state,'injury-treatment').totalAmount>0)actions.push(['doctor','Doctor','Restore hitpoints or treat persistent wounds']);
  if(getTownServiceQuote(state,'smithy').totalAmount>0)actions.push(['smithy','Smithy','Instantly repair equipped armor, attachments and shields']);
  const art={market:'trade_cart',recruit:'militia_trainingcamp_01',contracts:'townhall_02',retinue:'figure_player_troupe',doctor:'figure_player_seer',smithy:'workshop_01','ancient-armorer':'workshop_01','legendary-blacksmith':'legendary-blacksmith'};
  return actions.map(([action,label,description])=>`<button data-action="${action}"${cards?` class="settlement-service" title="${esc(description)}" aria-label="${label}: ${esc(description)}"`:''}>${cards?`<img src="./assets/world/${art[action]}.png" alt="" draggable="false"><strong>${label}</strong>`:label}</button>`).join('');
}

export function townStatusHTML(state,townId) {
  const icons=townFacilities(state.seed,town(townId)).map(f=>({id:f.id,label:f.name,detail:f.description,art:f.id==='blacksmith'?'ore_smelters_01':'workshop_01'}));
  if(!icons.length)icons.push({id:'general-traders',label:'General traders',detail:'A small rotating selection. Specialist workshops are available in other settlements.',art:'trade_cart'});
  const event=getTownEvent(state,townId),arts={'good-harvest':'wheat_field_02','poor-harvest':'wheat_field_02','trade-caravan':'trade_cart','market-fair':'trade_cart','armorer-shipment':'arms_cart','arms-shortage':'arms_cart','militia-muster':'militia_trainingcamp_01'};
  if(event)icons.push({id:'event',label:event.name,detail:`${event.description} ${event.effects.join(' ')} Through day ${event.endDay} · ${event.daysRemaining} ${event.daysRemaining===1?'day':'days'} left.`,art:arts[event.type]||'trade_cart',tone:['poor-harvest','arms-shortage'].includes(event.type)?'danger':'good'});
  for(const wagon of getCaravans(state).filter(c=>c.destinationId===townId&&['en-route','under-attack'].includes(c.status)))icons.push({id:wagon.id,label:wagon.status==='under-attack'?'Arms wagon threatened':'Arms incoming',detail:`${wagon.description} Arrival in ${Math.ceil(wagon.etaHours)} hours.`,art:'arms_cart',tone:wagon.status==='under-attack'?'danger':'trade'});
  const reward=getMountRewardEvents(state).find(e=>e.townId===townId&&!e.claimed);
  if(reward)icons.push({id:reward.id,label:reward.title,detail:reward.available?reward.scene:`${reward.name} may be offered around day ${reward.availableDay}.`,art:'figure_player_trader',tone:reward.available?'good':'trade'});
  const claim=reward?.available&&townAt(state)?.id===townId?`<button class="mount-status-claim" data-action="claim-mount-reward" data-claim-mount-reward="${esc(reward.id)}">${esc(reward.acceptLabel)}</button>`:'';
  return `<div class="town-status-strip" role="group" aria-label="Settlement status">${icons.map(icon=>{const tooltip=`town-status-${townId}-${icon.id}`;return `<span class="town-status"><button type="button" class="town-status-icon ${icon.tone||''}" aria-label="${esc(icon.label)}" aria-describedby="${esc(tooltip)}"><img src="./assets/world/${icon.art}.png" alt="" draggable="false">${icon.tone==='danger'?'<span class="town-status-warning" aria-hidden="true">!</span>':''}</button><span class="town-status-tooltip" id="${esc(tooltip)}" role="tooltip"><strong>${esc(icon.label)}</strong><span>${esc(icon.detail)}</span></span></span>`;}).join('')}</div>${claim}`;
}

export function inventoryProtectionText(item,condition,maximum=item.armor) {
  return `${condition??maximum} / ${maximum} durability · ${item.fatigue??0} fatigue`;
}

const woundTabsHTML = service => `<div class="wound-service-tabs" role="group" aria-label="Doctor services"><button data-town-service-view="doctor" aria-pressed="${service==='doctor'}">Restore HP</button><button data-town-service-view="injury-treatment" aria-pressed="${service==='injury-treatment'}">Treat wounds</button></div>`;

export function injuryPanelHTML(state,person,{compact=false}={}) {
  const wounds=getInjuryCare(state,person);
  if(!wounds.length)return '';
  const daily=injuryDailyMedicine(state.party),low=state.supplies.medicine<daily;
  return `<section class="injury-panel" aria-label="${esc(person.name)} injuries"><div class="injury-heading"><strong><span aria-hidden="true">✚</span> ${wounds.length} ${wounds.length===1?'wound':'wounds'}</strong>${companyHintHTML('injury-rules-'+person.id+'-'+compact,'Wound care','HP healing does not clear wounds. Each wound uses 1 medicine per day. Without medicine, recovery pauses. Doctor treatment halves recovery durations; it does not cure instantly.')}</div>${wounds.map(wound=>`<div class="injury-row"><span>${esc(wound.name)} ${companyHintHTML('wound-'+person.id+'-'+wound.id+'-'+compact,wound.name,injuryEffectText(wound))}</span><small>${wound.fresh?'New · after battle':wound.paused?'Paused':`${wound.remainingDays[0]===wound.remainingDays[1]?wound.remainingDays[1]:wound.remainingDays.join('–')}d`}${wound.treated?' · Treated':''}</small></div>`).join('')}${compact?'':`<div class="injury-care-summary"><small class="${low?'injury-warning':''}">${state.supplies.medicine<1?'Recovery paused · no medicine':`${daily} medicine/day · ${state.supplies.medicine} in stores${low?' · Care supplies low':''}`}</small>${townAt(state)&&!state.battle&&!state.gameOver?'<button class="small" data-town-service-view="injury-treatment">Wound care</button>':''}</div>`}</section>`;
}

function woundTreatmentHTML(state,quote) {
  const surgeon=hasRetinue(state,'surgeon');
  return `<section class="town-service">${woundTabsHTML(quote.service)}<div class="service-summary"><div><span class="supply-symbol supply-medicine" aria-hidden="true"></span><p>Halve wound recovery durations. ${companyHintHTML('treatment','Wound treatment','Treatment never instantly removes an injury or restores HP. Daily medicine is still needed. Price scales with remaining recovery and level; Surgeon gives a 25% discount before rounding.')}</p></div><strong>${state.gold} crowns</strong></div><div class="service-roster">${quote.entries.map(entry=>{const person=state.party.find(member=>member.id===entry.memberId);return `<article class="service-brother">${portraitHTML(person,getEquipment(person),72)}<div class="service-details"><h3>${esc(entry.name)}</h3>${injuryPanelHTML(state,person,{compact:true})||'<small>No injuries</small>'}</div><div class="service-payment"><button data-town-service="injury-treatment" data-service-member="${esc(entry.memberId)}" ${entry.amount<1||entry.cost>state.gold?'disabled':''}>${entry.amount?`Treat · ${entry.cost} crowns`:'No treatment needed'}</button></div></article>`;}).join('')}</div><div class="service-total"><small>${injuryDailyMedicine(state.party)} medicine/day${surgeon?' · Surgeon: 1 day sooner':''}</small><button class="primary" data-town-service="injury-treatment" ${!quote.ok?'disabled':''} aria-label="Treat all untreated wounds for ${quote.totalCost} crowns">Treat all · ${quote.totalCost} crowns</button></div></section>`;
}

export function townServiceHTML(state, quote) {
  if(quote.service==='injury-treatment')return woundTreatmentHTML(state,quote);
  const doctor=quote.service==='doctor', verb=doctor?'Heal':'Repair';
  const description=doctor?(hasRetinue(state,'surgeon')?'Restore missing hitpoints. Surgeon discount −25%; rounded up per brother.':'Restore missing hitpoints. 1 crown per hitpoint.'):'Restore equipped armor, attachments, and active or reserve shields. 1 crown per 2 durability, rounded up per brother.';
  return `<section class="town-service">${doctor?woundTabsHTML(quote.service):''}<div class="service-summary"><div><span class="supply-symbol ${doctor?'supply-medicine':'supply-tools'}" aria-hidden="true"></span><p>${description}<br>Immediate service. Your ${doctor?'medicine is':'tools are'} not consumed.</p></div><strong>${state.gold} crowns</strong></div><div class="service-roster">${quote.entries.map(entry=>{
    const person=state.party.find(member=>member.id===entry.memberId), needsWork=entry.amount>0, affordable=state.gold>=entry.cost;
    const details=doctor?`<p class="service-condition"><strong>${entry.currentHp} / ${entry.maxHp}</strong> hitpoints${needsWork?` <span>+${entry.amount} to restore</span>`:''}</p>`:entry.repairs.map(repair=>`<div class="service-gear">${itemIcon(item(repair.itemId),'')}<span>${repair.slot==='shield'?`${repair.set==='reserve'?'Reserve':'Active'} `:''}${esc(item(repair.itemId)?.name)}<small>${repair.current} / ${repair.max} durability${repair.missing?` · +${repair.missing} to restore`:''}${repair.slot==='shield'&&repair.current===0?' · Broken':''}</small></span></div>`).join('')||'<p class="service-condition">No repairable gear equipped.</p>';
    return `<article class="service-brother">${portraitHTML(person,getEquipment(person),72)}<div class="service-details"><h3>${esc(entry.name)}</h3>${details}</div><div class="service-payment"><button data-town-service="${quote.service}" data-service-member="${esc(entry.memberId)}" aria-label="${verb} ${esc(entry.name)} for ${entry.cost} crowns" ${!needsWork||!affordable?'disabled':''}>${needsWork?`${verb} · ${entry.cost} crowns`:doctor?'Fully healed':'Gear ready'}</button>${needsWork&&!affordable?`<small>Need ${entry.cost-state.gold} more crowns</small>`:''}</div></article>`;
  }).join('')}</div><div class="service-total"><div><strong>${quote.totalAmount?`${quote.totalAmount} ${doctor?'hitpoints':'durability'} to restore`:doctor?'Everyone is fully healed.':'All equipped gear is ready.'}</strong><p>${quote.totalAmount?`Company total: ${quote.totalCost} crowns`:'No charge needed.'}</p>${quote.totalAmount&&state.gold<quote.totalCost?`<small>Need ${quote.totalCost-state.gold} more crowns for everyone. You can ${doctor?'heal':'repair for'} individual brothers above.</small>`:''}</div><button class="primary" data-town-service="${quote.service}" ${!quote.ok?'disabled':''}>${doctor?'Heal everyone':'Repair all equipped'} · ${quote.totalCost} crowns</button></div><p class="service-note">${doctor?'Fallen brothers cannot be revived.':'Active and reserve shields can break and be repaired here. Weapons do not wear down; stashed items are not included.'}</p></section>`;
}

export function townEventHTML(state, townId, compact=false) {
  const event=getTownEvent(state,townId);
  if(!event)return '';
  return `<section class="town-event ${compact?'compact':''}"><div class="town-event-heading"><strong>${esc(event.name)}</strong><small>Through day ${event.endDay} · ${event.daysRemaining} ${event.daysRemaining===1?'day':'days'} left</small></div>${compact?'':`<p>${esc(event.description)}</p>`}<p class="town-event-effects">${event.effects.map(esc).join(' · ')}</p></section>`;
}

export function mountRewardHTML(state, townId, compact=false) {
  const event=getMountRewardEvents(state).find(entry=>entry.townId===townId);
  if(!event)return '';
  const status=event.claimed?'This one-time mount reward has already been claimed.':event.available?event.scene:`Word is spreading that ${event.name.toLowerCase()} may be offered here around day ${event.availableDay}.`;
  const claim=event.available&&!event.claimed?(townAt(state)?.id===townId?`<button class="primary" data-action="claim-mount-reward" data-claim-mount-reward="${esc(event.id)}">${esc(event.acceptLabel)}</button><small>There is no charge. The mount goes straight to your stash; if it is full, make room and return.</small>`:'<small>Visit this settlement to accept the offer.</small>'):'';
  return `<section class="mount-reward ${compact?'compact':''}"><div class="town-event-heading"><strong>${esc(event.title)}</strong><small>${event.townName} · ${event.claimed?'Claimed':event.available?'Available now':`Day ${event.availableDay}`}</small></div><p>${esc(status)}</p>${claim}</section>`;
}

const caravanStatus = { 'en-route':'On the road', 'under-attack':'Raiders closing', delivered:'Delivered', lost:'Shipment lost' };
const caravanActive = caravan => caravan.status==='en-route'||caravan.status==='under-attack';
const caravanContact = caravan => caravan.contact===true||(caravan.contact==null&&caravan.status==='under-attack');
const hoursText = hours => `${Math.max(0,Math.ceil(hours*10)/10)}h`;

export function caravanSidebarHTML(state, caravan) {
  if (caravan.quest) return `<div class="location-header caravan-location"><div class="eyebrow">Contract · Caravan rescue</div><h2>${esc(caravan.name)}</h2><img class="caravan-portrait" src="./assets/world/figure_player_trader.png" alt=""><p class="caravan-status under-attack">Battle awaiting your arrival</p></div><div class="caravan-report"><p>Raiders have surrounded this caravan. Its three guards will fight beside your company when you join the rescue.</p><p>The battle begins when you reach the wagon.</p></div><div class="stack"><button class="primary" data-quest-travel="rescue" data-target-id="${esc(caravan.id)}">Join the rescue</button><button data-action="company">Inspect your company</button></div>`;
  const origin=town(caravan.originId), destination=town(caravan.destinationId), active=caravanActive(caravan), bands=getRoamingBands(state);
  const attacker=active?bands.find(band=>band.id===caravan.attackerId):null;
  const raiding=active?(bands.find(band=>band.behavior==='raiding-caravan'&&band.targetId===caravan.id)||attacker):null;
  const inContact=active&&caravanContact(caravan);
  const visibleStatus=inContact?'Wagon intercepted':raiding?'Raiders closing':caravanStatus[caravan.status];
  const raidText=inContact
    ? `${esc(raiding?.name||'Brigands')} have reached the wagon. Defeat them within ${hoursText(caravan.attackHoursRemaining)}; the shipment is lost only if raiders still hold the wagon when time runs out.`
    : `${esc(raiding?.name||'Brigands')} are closing on this wagon. They have not caught it yet. Defeat these raiders to protect the shipment.`;
  return `<div class="location-header caravan-location"><div class="eyebrow">Friendly armory caravan</div><h2>${esc(caravan.name)}</h2><img class="caravan-portrait" src="./assets/world/figure_player_trader.png" alt=""><p class="caravan-status ${caravan.status}">${visibleStatus}</p></div><p class="caravan-route">${esc(origin?.name)} &rarr; ${esc(destination?.name)}</p><p class="location-description">${esc(caravan.description)}</p>${caravanActive(caravan)?`<div class="caravan-report"><p><strong>Arrival in ${hoursText(caravan.etaHours)}</strong></p>${caravan.status==='under-attack'||raiding?`<p class="caravan-danger">${raidText}</p>`:'<p>No band is attacking this caravan.</p>'}</div><div class="stack">${raiding?`<button class="primary" data-caravan-attacker="${raiding.id}">Pursue ${esc(raiding.name)}</button>`:''}<button class="${raiding?'':'primary'}" data-follow-caravan="${caravan.id}">Follow caravan</button><button data-event-town="${caravan.destinationId}">Show destination</button><button data-action="market-news">Market news</button></div><p class="caravan-note">Time pauses during battle.</p>`:`<div class="stack"><button data-event-town="${caravan.destinationId}">Show ${esc(destination?.name)} on map</button><button data-action="market-news">Market news</button></div>`}`;
}

export function caravanListHTML(state, compact=false) {
  const bands=getRoamingBands(state), caravans=getCaravans(state), visible=compact?caravans.filter(caravanActive):caravans;
  if(!visible.length)return '';
  return `<section class="caravan-list ${compact?'compact':''}"><h3>${compact?'Caravans on the road':'Armory caravans'}</h3>${visible.map(caravan=>{const active=caravanActive(caravan),raiding=!caravan.quest&&bands.some(band=>band.behavior==='raiding-caravan'&&band.targetId===caravan.id),contact=!caravan.quest&&active&&caravanContact(caravan),phase=caravan.quest?'Battle awaiting your arrival':contact?'Wagon intercepted':raiding?'Raiders closing':caravanStatus[caravan.status];return `<button class="caravan-listing ${caravan.status} ${raiding?'has-raiders':''}" data-select-caravan="${caravan.id}"><img src="./assets/world/figure_player_trader.png" alt=""><span><strong>${esc(caravan.quest?caravan.name:town(caravan.destinationId)?.name)}</strong><small>${phase}${caravan.quest?'':caravan.status==='under-attack'&&contact?` · ${hoursText(caravan.attackHoursRemaining)} to intervene`:active?` · ${hoursText(caravan.etaHours)} to arrive`:''}</small></span><span aria-hidden="true">&rarr;</span></button>`;}).join('')}</section>`;
}

export function marketNewsHTML(state) {
  const events=getTownEconomy(state).events;
  return `<section class="market-news"><p class="market-news-intro">Highpass receives one Riding Horse on days 8, 22, 36 and every 14 days thereafter, on sale until bought or the next weekly rotation. Rare war horses and wolves may appear in large towns and castles. Word from the trade roads. Large town armorer caravans depart every 12 days and take 60 hours to travel. Clear raiders to help them arrive; a lost shipment leaves a temporary shortage where equipment sells for more. Prices may change before you reach town.</p>${caravanListHTML(state)}<div class="market-news-grid">${events.map(event=>`<article class="market-news-card"><div class="eyebrow">${esc(event.town.kind)} · ${esc(event.town.name)}</div>${townEventHTML(state,event.town.id)}<button data-event-town="${event.town.id}">Show ${esc(event.town.name)} on map</button></article>`).join('')||'<p>The markets are quiet today. New local events arrive throughout the fortnight.</p>'}</div><p class="market-news-note">Completed courier jobs have a 25% chance to bring one extra piece of equipment to the destination market. Check the chronicle for arrivals.</p></section>`;
}

const bonusText = bonuses => Object.entries(bonuses || {}).map(([key,value])=>`${value>0?'+':''}${value} ${statLabels[key] || key}`).join(' · ');
const traitHTML = trait => `<div class="recruit-trait ${trait.kind}"><strong>${esc(trait.name)}${trait.kind==='tradeoff'?'<small>Trade-off</small>':''}</strong><span>${esc(bonusText(trait.bonuses))}</span></div>`;

function backgroundHTML(person) {
  const background=getBackground(person), traits=getTraits(person);
  return `<section class="brother-background"><h3>${esc(background.name)} ${companyHintHTML('background','Background',`${background.description} ${bonusText(background.bonuses)}`)}</h3>${traits.length?`<div class="company-trait-chips">${traits.map((trait,index)=>`<span>${esc(trait.name)} ${companyHintHTML(`trait-${index}`,trait.name,`${trait.kind==='tradeoff'?'Trade-off. ':''}${bonusText(trait.bonuses)}`)}</span>`).join('')}</div>`:''}</section>`;
}

export function hiringHTML(state, offers) {
  const labels={maxHp:'Hitpoints',meleeSkill:'Melee skill',rangedSkill:'Ranged skill',meleeDefense:'Melee defense',rangedDefense:'Ranged defense',maxFatigue:'Max. fatigue',initiative:'Initiative',resolve:'Resolve'};
  return `<section class="hiring-board"><div class="hiring-summary"><span>${state.party.length} / ${MAX_COMPANY_SIZE} companions · ${getBattleRoster(state).length} / ${MAX_BATTLE_SIZE} fielded · Day ${state.day}</span><strong>${state.gold} crowns</strong></div><p class="hiring-intro">${esc(SETTLEMENT_TYPES[townAt(state)?.kind]?.summary || "")} Choose a companion. Every strength and trade-off is shown; new faces arrive tomorrow. Stars show growth potential: ★ adds +1, ★★ adds +2, ★★★ guarantees +5 at level-up (maximum +5). Backgrounds never restrict weapons or perks.</p><div class="recruit-grid">${offers.map(offer=>{const {person,background,traits,stats,cost}=offer,full=state.party.length>=MAX_COMPANY_SIZE,poor=state.gold<cost;return `<article class="recruit-card"><div class="recruit-heading">${portraitHTML(person,getEquipment(person),64)}<div><div class="eyebrow">${esc(background.role)}</div><h3>${esc(person.name)}</h3><strong>${esc(background.name)}</strong></div></div><div class="recruit-history"><p>${esc(background.description)}</p><p class="background-bonus">${esc(bonusText(background.bonuses))}</p></div><div class="recruit-traits">${traits.map(traitHTML).join('')}</div><dl class="recruit-stats">${Object.entries(labels).map(([key,label])=>`<div><dt>${label}${talentHTML(person,key)}</dt><dd>${stats[key]}</dd></div>`).join('')}</dl><div class="recruit-hire"><p>${stats.dailyWage} crowns + 1 food / day<br>Arrives without equipment.</p><button class="primary" data-hire-recruit="${esc(offer.id)}" aria-label="Hire ${esc(person.name)} for ${cost} crowns" ${full||poor?'disabled':''}>${full?'Company full':poor?`Need ${cost-state.gold} more crowns`:`Hire · ${cost} crowns`}</button>${full||poor?`<small>Hiring fee: ${cost} crowns</small>`:''}</div></article>`;}).join('')||'<p class="hiring-empty">All available companions have joined you. Come back tomorrow for new recruits.</p>'}</div></section>`;
}

export function resourceHTML(state, speed) {
  const light=getTimeOfDay(state.hour);
  const dailyCare=injuryDailyMedicine(state.party??[]),medicine=state.supplies?.medicine??0;
  const values = [
    ['money',state.gold.toLocaleString(),'Crowns'],
    ['food',state.food,`Provisions · ${Math.floor(state.food / (getDailyFood(state)||1))} days`],
    ['tools',state.supplies?.tools ?? 0,'Tools & supplies'],
    ['medicine',medicine,dailyCare?`Medicine · ${dailyCare}/day`:'Medicine'],
    ['ammo',state.supplies?.ammo ?? 0,'Ammunition'],
  ];
  return values.map(([kind,value,label])=>`<div class="resource resource-${kind}${kind==='medicine'&&dailyCare>medicine?' resource-care-low':''}" title="${kind==='medicine'&&dailyCare?esc(`${dailyCare} medicine per day for wounds. ${medicine<1?'Recovery paused: no medicine.':medicine<dailyCare?'Not enough for all wounds tomorrow.':'Daily wound care supplied.'}`):label}"><span class="supply-symbol supply-${kind}" aria-hidden="true"></span><span><strong>${value}</strong><small>${label}</small></span></div>`).join('') + `<div class="resource clock"><span><strong>Day ${state.day} · ${light.label}</strong><small>${String(Math.floor(state.hour)).padStart(2,'0')}:00 · ${speed?(state.pursuit?'Pursuing':state.destination?'On the march':'Waiting'):'Paused'}</small></span></div>`;
}

export function formationHTML(state, selectedIndex=null) {
  const savedFormation=getFormation(state);
  const formation=[...Array.from({length:36},(_,index)=>savedFormation[index]??null),...getReserveSlots(state)];
  const selectedId=Number.isInteger(selectedIndex)?formation[selectedIndex]:null;
  const selectedPerson=state.party.find(person=>person.id===selectedId);
  const slot=(index,line,position)=>{
    const member=state.party.find(person=>person.id===formation[index]);
    const selected=index===selectedIndex;
    return `<button class="formation-slot ${member?'is-occupied':'is-empty'} ${selected?'is-selected':''}" data-formation-slot="${index}" aria-pressed="${selected}" aria-label="${line} position ${position}: ${member?esc(member.name):'empty'}${selected?', selected':''}">${member?`${portraitHTML(member,getEquipment(member),34)}<span><strong>${esc(member.name)}</strong><small>${selected?'Selected · tap a destination':`${line} ${position}`}</small></span>`:`<span class="formation-empty"><strong>Empty</strong><small>${line} ${position}</small></span>`}</button>`;
  };
  const line=(name,start)=>Array.from({length:12},(_,row)=>slot(start+row,name,row+1)).join('');
  return `<section class="formation-editor"><div class="formation-capacity">${getBattleRoster(state).length} / ${MAX_BATTLE_SIZE} fielded · ${getReserveSlots(state).filter(Boolean).length} / 3 reserves · ${state.party.length} / ${MAX_COMPANY_SIZE} company</div><p class="formation-help" role="status">${selectedPerson?`${esc(selectedPerson.name)} selected. Tap another position to move or swap; tap the selected position again to cancel.`:'Tap a fighter, then tap another position to move or swap.'}</p><div class="formation-board"><section class="formation-column formation-rear"><h3>Rear</h3><div class="formation-line">${line('Rear',24)}</div></section><section class="formation-column formation-middle"><h3>Middle</h3><div class="formation-line">${line('Middle',12)}</div></section><section class="formation-column formation-front"><h3>Front</h3><div class="formation-line">${line('Front',0)}</div></section><div class="formation-enemy" aria-label="Enemies approach from the right"><span aria-hidden="true">&rarr;</span><strong>Enemy line</strong></div></div><section class="formation-reserves"><h3>Reserves · stay out of battle</h3><div class="formation-reserve-line">${Array.from({length:3},(_,i)=>slot(36+i,'Reserve',i+1)).join('')}</div></section><p class="formation-note">Swap fielded brothers with reserves before fighting. Reserves keep their gear and receive no combat XP. Front positions begin closest to the enemy; Middle and Rear begin progressively farther back. Formation is locked once battle begins.</p></section>`;
}

function conditionRow(label, current, max, type, status='') {
  return `<div class="condition-row"><span>${label}</span><div class="condition-meter ${type}"><i style="width:${max ? Math.max(0,Math.min(100,current/max*100)) : 0}%"></i><strong>${Math.round(current)} / ${max}${status?` · ${status}`:''}</strong></div></div>`;
}

export function equipmentSetHTML(person){
 const status=equipmentSetStatus(person,getItem);if(!status)return '';
 const {set,count,active}=status,load=effectiveArmorFatigue(person,getItem);
 const detail=active?`Both pieces worn: +${set.armorPct}% head and body armor; helmet fatigue −${set.headFatiguePct}%, body fatigue −${set.bodyFatiguePct}%. Effective load: body ${load.body}, head ${load.head}. Set fitting applies before Nimble, Agile Defense, Fleet Footed and Brawny. Fatigue rounds to the nearest integer; damaged armor is never repaired.`:`${set.pairing} Activate +${set.armorPct}% head/body armor and reduced armor fatigue. Ordinary, named and reforged versions of these designs count. Stashed pieces do not count.`;
 const chain=active?'<path d="M10 13a5 5 0 0 0 7 .7l3-3a5 5 0 0 0-7-7l-2 2M14 11a5 5 0 0 0-7-.7l-3 3a5 5 0 0 0 7 7l2-2"/>':'<path d="m9 15-2 2a4 4 0 0 1-5-6l3-3a4 4 0 0 1 5 0m4 1 2-2a4 4 0 0 1 6 5l-3 3a4 4 0 0 1-5 0M9 3l1 3m-7 3 3 1m12 4 3 1m-7 3 1 3"/>';
 const label=`${set.name} ${count}/2 · ${active?'Matching set active':'Pair incomplete'}`;
 return companyHintHTML('armor-set',label,detail)
  .replace('class="company-hint"',`class="company-hint armor-set-link${active?' is-active':''}"`)
  .replace('>?</button>',`><svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">${chain}</svg></button>`);
}

export function companySheetHTML(state, person, filter, inventory) {
  const stats = getCompanyStats(person), gear = getEquipment(person);
  const reserve = { weapon:item(person.reserveEquipment?.weapon), shield:item(person.reserveEquipment?.shield) };
  const accessories = [item(person.accessories?.[0]),item(person.accessories?.[1])];
  const training = stats.trainingPoints ?? person.trainingPoints ?? 0;
  const perkPoints = getPerkPoints(person), learned = PERKS.filter(perk => person.perks?.includes(perk.id));
  const body = (stats.bodyArmor ?? 0) + (stats.attachmentArmor ?? 0) + (stats.attachment2Armor ?? 0), head = stats.headArmor ?? gear.helmet?.armor ?? 0;
  const maxBody = (stats.maxBodyArmor ?? 0) + (stats.maxAttachmentArmor ?? 0) + (stats.maxAttachment2Armor ?? 0);
  const equipmentSlot=(slot,entry,location,label)=>`<div class="slot-wrap"><button class="slot ${filter===slot||(slot==='accessory'&&filter==='accessory')?'active':''}" ${entry?`data-inspect="${entry.id}" data-item-source="equipped" data-item-location="${location}" data-item-slot="${slot}"`:`data-slot="${slot}"`}><small>${label}</small>${entry?itemIcon(entry):'<span class="empty-slot">Empty</span>'}<strong>${entry?.name||'Unequipped'}</strong></button>${entry?`<button class="stow-button" data-unequip="${slot}" data-equipment-location="${location}">Stow</button>`:''}${slot==='helmet'?equipmentSetHTML(person):''}</div>`;
  return `<section class="page company-page"><div class="page-heading"><div><div class="eyebrow">${esc(person.background)} · LEVEL ${stats.level || 1} · ${getReserveSlots(state).includes(person.id)?'RESERVE':'FIELDED'}</div><h1>${esc(person.name)}</h1><p>${state.party.length} / ${MAX_COMPANY_SIZE} brothers · ${state.renown} renown</p></div><div class="button-row"><button data-tab="world">Return to the world map</button></div></div>
  <div class="company-layout detailed-company"><article class="character-card"><div class="hero-portrait">${portraitHTML(person,gear,150)}</div>
  <div class="condition-list">${conditionRow('Head',head,stats.maxHeadArmor||0,'armor')}${conditionRow('Body',body,maxBody,'armor')}${gear.shield?conditionRow('Shield',stats.shieldDurability,stats.maxShieldDurability,'armor',stats.shieldDurability===0?'Broken':''):''}${conditionRow('Hitpoints',person.hp,stats.maxHp,'health')}</div>
  <div class="experience-bar"><i style="width:${Math.min(100,((stats.xp||0)/Math.max(1,stats.nextLevelXp||100))*100)}%"></i><span>${stats.level>=30?'Maximum level reached':`${stats.xp||0} / ${stats.nextLevelXp||100} experience`}</span></div>
  <div class="company-condition-summary"><span>${esc(getMoraleEffects(person).name)} · ${person.morale} ${companyHintHTML('morale','Morale',`In battle: ${getMoraleEffects(person).modifier>0?'+':''}${Math.round(getMoraleEffects(person).modifier*100)}% attack and defense. Resolve reduces morale loss.`)}</span><span class="${person.hp<stats.maxHp?'is-wounded':''}">${person.injuries?.length?'Injured':person.hp<stats.maxHp?'Wounded · recovering':'Uninjured'}</span></div>${injuryPanelHTML(state,person)}  <div class="attribute-list">${Object.entries(statLabels).map(([key,label])=>`<div><span>${label}${talentHTML(person,key)}</span><strong>${stats[key] ?? 0}</strong></div>`).join('')}</div>${training?`<div class="training-ready"><p>${training} ${training===1?'level-up':'level-ups'} ready · Choose 3 attributes per level</p><button class="primary" data-action="level-up">Level up ${esc(person.name.split(' ')[0])}</button></div>`:''}${backgroundHTML(person)}<section class="brother-perks"><h3>Perks ${companyHintHTML('perks','Perks','Earn one perk point with every level-up. Tap a learned perk to inspect it.')}${perkPoints?` <small>${perkPoints} available</small>`:''}</h3><button class="${perkPoints?'primary':''}" data-action="perks">${perkPoints?'Choose a perk':'View perks'}</button>${learned.length?`<div class="learned-perks">${learned.map(perk=>`<button data-view-perk="${perk.id}" aria-label="Inspect ${esc(perk.name)}" title="${esc(perk.description)}"><img src="./assets/perks/${perk.icon||perk.id}.png" alt=""></button>`).join('')}</div>`:''}</section></article>
<section class="equipment-panel equipment-panel-v11"><h3>Equipment ${companyHintHTML('equipment','Equipment','Choose the starting set here. Fighters handle reserve gear and accessories automatically in battle. Tap equipped gear to inspect it; Stow moves it to the company stash.')}</h3>${combatSettingsHTML(person)}<h4>Protection ${companyHintHTML('protection','Armor attachments','Layered Armor unlocks a second attachment. Each layer has separate durability and repairs; attachment 2 absorbs body damage first, then attachment 1, then the main suit. Attachment weight does not count toward Nimble, Agile Defense or Fleet Footed. Padding stays beneath the armor; outer mantles and pauldrons appear on the portrait.')}</h4><div class="equipment-slots protection-slots">${equipmentSlot('helmet',gear.helmet,'active','Head armor')}${equipmentSlot('armor',gear.armor,'active','Body armor')}${equipmentSlot('attachment',gear.attachment,'active','Attachment 1')}${hasEquipmentPerk(person,'layered-armor')?equipmentSlot('attachment',gear.attachment2,'attachment-2','Attachment 2'):'<div class="slot-wrap"><button class="slot" disabled><small>Attachment 2</small><span class="empty-slot">Locked</span><strong>Requires Layered Armor</strong></button></div>'}</div><div class="equipment-set-heading"><h4>Active set</h4><button class="swap-set-button" data-swap-weapon-set="${person.id}" ${reserve.weapon||reserve.shield?'':'disabled'}>Swap sets</button></div><div class="equipment-slots">${equipmentSlot('weapon',gear.weapon,'active','Active weapon')}${equipmentSlot('shield',gear.shield,'active','Active shield')}</div><h4>Reserve set ${companyHintHTML('reserve','Reserve set','Weapons and shields can start active or in reserve. Swap sets before combat, or let fighters switch as needed in battle. Quick Hands grants one free weapon swap per round; otherwise swaps cost 4 AP.')}</h4><div class="equipment-slots">${equipmentSlot('weapon',reserve.weapon,'reserve','Reserve weapon')}${equipmentSlot('shield',reserve.shield,'reserve','Reserve shield')}</div><h4>Mount &amp; accessories ${companyHintHTML('mount','Riding mount',`${gear.mount?gear.mount.description:'Find rare mounts in large town and castle markets, or capture a mount from a defeated rider.'} Mounts add daily food upkeep.`)}${companyHintHTML('accessories','Accessories','Remedies and pocket daggers fit either accessory slot. At half health or lower, fighters prioritize carried healing items, even in melee. Remedies cost 4 AP; Combat Bandaging grants one free healing item per round. Empty-ammo archers draw a pocket dagger or reserve melee weapon.')}</h4><div class="equipment-slots utility-slots">${equipmentSlot('mount',gear.mount,'active','Riding mount')}${equipmentSlot('accessory',accessories[0],'accessory-1','Accessory 1')}${equipmentSlot('accessory',accessories[1],'accessory-2','Accessory 2')}</div><p class="mount-summary" aria-label="Company travel bonus: +${Math.round(getCompanyTravelBonus(state)*100)}%">Travel +${Math.round(getCompanyTravelBonus(state)*100)}%</p>
</section>
  <aside class="inventory-panel"><div class="inventory-title"><h3>Company stash ${companyHintHTML('stash','Company stash','Tap gear to inspect it and choose its exact slot. Weapons and shields can start active or in reserve. Remedies and pocket daggers fit either accessory slot. Mounts use their own slot.')}</h3><span>${state.inventory.length} / ${getStashCapacity(state)} items</span></div><div class="filter-tabs">${['all','armor','helmet','attachment','weapon','shield','accessory','mount'].map(slot=>`<button class="small ${filter===slot?'active':''}" data-slot="${slot}">${slot==='all'?'All':slot[0].toUpperCase()+slot.slice(1)}</button>`).join('')}</div><div class="inventory-grid">${inventory}</div><button class="primary" data-action="market">Visit the marketplace</button><div class="company-recovery">Recovery ${companyHintHTML('recovery','After a battle','Rest to heal wounds and repair damaged armor. Medicine and tools are consumed. Fallen brothers stay dead. Victory allows their equipment to be recovered.')}</div></aside></div></section>`;
}

export function levelUpHTML(person, selected=[]) {
  const pending = getLevelUp(person);
  if (!pending) return '';
  const stats = getCompanyStats(person);
  return `<section class="level-up"><p class="level-up-instructions">Choose <strong>3 different attributes</strong> for level ${pending.level}. Each offers a saved bonus of +1 to +5. Talents add +1 (★), +2 (★★), or guarantee +5 (★★★), capped at +5. You can change your choices before confirming.</p><div class="level-up-count" role="status">${selected.length} / 3 selected</div><div class="level-up-grid">${Object.entries(statLabels).map(([key,label])=>{const chosen=selected.includes(key),gain=pending.rolls[key],after=getCompanyStats({...person,attributes:{...person.attributes,[key]:(person.attributes?.[key]??0)+gain}})[key];return `<button class="level-up-stat ${chosen?'chosen':''}" data-level-stat="${key}" aria-pressed="${chosen}" aria-label="${esc(label)} +${gain}" ${selected.length===3&&!chosen?'disabled':''}><span>${label}${talentHTML(person,key)}</span><strong>${stats[key]}${chosen?` <span aria-hidden="true">→</span> ${after}`:''}</strong><span class="level-up-gain">+${gain}</span><small>${chosen?'Selected':'Choose'}</small></button>`;}).join('')}</div><p class="level-up-note">These rolls are saved for this level. Perks apply after the attribute increase. Closing this panel or reloading will not reroll them.</p><div class="button-row level-up-actions"><button class="primary" data-action="confirm-level-up" ${selected.length!==3?'disabled':''}>Confirm 3 attributes</button><button data-action="close-modal">Choose later</button></div></section>`;
}

export function perksHTML(person, selectedId=null) {
  const points=getPerkPoints(person), level=person.level??1;
  const learned=new Set(person.perks??[]), selected=PERKS.find(perk=>perk.id===selectedId);
  const canLearn=selected&&!learned.has(selected.id)&&level>=selected.minLevel&&points>0;
  const categories={general:'Melee & damage',weapon:'Weapon masteries',defense:'Defense & shields',ranged:'Ranged combat',mobility:'Mobility & stamina'};
  const groups=Object.entries(categories).map(([id,label])=>`<section class="perk-category"><h3>${label}</h3><div class="perk-grid">${PERKS.filter(perk=>(perk.category||'general')===id).sort((a,b)=>a.minLevel-b.minLevel||a.name.localeCompare(b.name)).map(perk=>{
    const owned=learned.has(perk.id),locked=level<perk.minLevel;
    return `<button class="perk-card ${owned?'learned':''} ${locked?'locked':''} ${perk.id===selectedId?'chosen':''}" data-perk="${perk.id}" aria-pressed="${perk.id===selectedId}" aria-label="${esc(perk.name)}${owned?', learned':locked?`, unlocks at level ${perk.minLevel}`:''}"><img src="./assets/perks/${perk.icon||perk.id}.png" alt=""><span><strong>${esc(perk.name)}</strong><small>${owned?'Learned':locked?`Requires level ${perk.minLevel}`:'1 perk point'}</small></span><p>${esc(perk.description)}</p></button>`;
  }).join('')}</div></section>`).join('');
  return `<section class="perk-picker"><p class="perk-intro"><strong>${points} perk ${points===1?'point':'points'} available</strong> · Level ${level}<br>Gain one point every level after the first. Each perk costs one point and can be learned once. Unspent points stay with this brother. Mix specializations to build your role.</p>${groups}<div class="perk-actions"><p role="status">${selected?`${esc(selected.name)}: ${learned.has(selected.id)?'Already learned.':level<selected.minLevel?`Unlocks at level ${selected.minLevel}.`:points?'Ready to learn.':'No perk points available.'}`:'Select a perk to review, then learn it.'}</p><div class="button-row"><button class="primary" data-action="learn-perk" ${canLearn?'':'disabled'}>${selected?`Learn ${esc(selected.name)}`:'Learn selected perk'}</button><button data-action="close-modal">Done</button></div></div></section>`;
}

export function difficultyHTML(level=1) {
  return `<span class="difficulty" role="img" aria-label="Difficulty ${level} of 3"><span style="width:${Math.min(3,Math.max(1,level))*9.5}px"></span></span>`;
}

export function campSidebarHTML(state, site) {
  if(site.kind.startsWith('undead-')){
    const near=!state.destination&&Math.hypot(site.x-state.position.x,site.y-state.position.y)<=35;
    return `<div class="location-header hostile-location"><div class="eyebrow">Ashen Winter · ${esc(site.kind.replace('undead-',''))}</div><h2>${esc(site.name)}</h2><p>${esc(site.description)}</p><p>${site.enemies.length} undead · ${site.reward} crowns${site.kind==='undead-liberation'?' · restores all services':''}</p></div><div class="scout-enemies">${site.enemies.map((enemy,index)=>`<div>${portraitHTML({name:enemy.name,seed:index},Object.fromEntries(['armor','helmet','weapon','shield'].map(slot=>[slot,item(enemy[slot])])),50)}<strong>${esc(enemy.name)}</strong></div>`).join('')}</div><p>The dead cannot flee or lose morale. Check your armor, ammunition, and formation.</p><button class="primary" ${near?`data-engage="${site.id}"`:`data-quest-travel="${site.kind}" data-target-id="${site.id}"`}>${site.kind==='undead-liberation'?'Liberate settlement':site.kind==='undead-commander'?'Destroy stronghold':'Intercept host'}</button>`;
  }
  if(site.kind==='patrol')return `<div class="location-header"><div class="eyebrow">${esc(site.playerRelation)} soldiers · ${esc(site.factionLabel)}</div><h2>${esc(site.name)}</h2><p>${esc(site.description)}</p><p>Home: ${esc(town(site.homeId)?.name)} · ${site.enemies.length}/${site.size} soldiers</p><p>${site.active?esc(site.behavior.replaceAll('-',' ')):`Reforming · ${site.respawnHours}h remaining`} · ${site.wins} victories · ${site.losses} defeats</p><p>Tour: ${site.tour.map(id=>esc(town(id)?.name)).join(' → ')}</p></div><div class="scout-enemies">${site.enemies.map((enemy,index)=>`<div>${portraitHTML({name:enemy.name,seed:index},Object.fromEntries(['armor','helmet','weapon','shield','mount'].map(slot=>[slot,item(enemy[slot])])),50)}<strong>${esc(enemy.name)}</strong>${enemy.mount?`<small>${esc(item(enemy.mount)?.name)}</small>`:''}${enemy.champion?`<small class="champion-trophy">★ Champion · guaranteed ${esc(item(enemy.championItemId)?.name)}</small>`:''}</div>`).join('')}</div>${site.joinableBattle?`<button class="primary" data-join-patrol="${esc(site.id)}">Join ${site.playerRelation==='ally'?'allied':'patrol'} battle</button>`:''}<button data-action="nearest-town">Select nearest settlement</button>`;

  const near = !state.destination && Math.hypot(site.x-state.position.x,site.y-state.position.y) <= 35;
  const cleared = site.cleared;
  const roaming=site.kind==='band', pursuing=state.pursuit===site.id;
  const count=cleared?0:site.enemies?.length||0;
  const enemyGear=enemy=>Object.fromEntries(['armor','helmet','attachment','weapon','shield','mount'].map(slot=>[slot,item(enemy[slot])]));
  const scoutRoster=cleared?'':`<div class="scout-enemies">${site.enemies.map((enemy,index)=>`<div>${portraitHTML({name:enemy.name,seed:index},enemyGear(enemy),50)}<strong>${esc(enemy.name)}</strong>${enemy.mount?`<small>${esc(item(enemy.mount)?.name)}</small>`:''}${enemy.champion?`<small class="champion-trophy">★ Champion · guaranteed ${esc(item(enemy.championItemId)?.name)}</small>`:''}</div>`).join('')}</div>`;
  const mountNote=site.mountChance?`<p>High-tier camp reward: ${Math.round(site.mountChance*100)}% chance of an extra mount, alongside named loot.</p>`:'';
  const famedChance=Math.round((Number(site.famedChance)||0)*100);
  const caravan=roaming&&site.behavior==='raiding-caravan'?getCaravans(state).find(entry=>entry.id===site.targetId):null;
  const activity=site.behavior==='hunting-company'?'Pursuing your company':site.behavior==='raiding-caravan'?`Raiding ${town(caravan?.destinationId)?.name||'a'} wagon`:'Patrolling';
  const raidPhase=caravan&&caravanContact(caravan)?'Wagon intercepted':'Closing on the wagon';
  const sanctuary=roaming&&site.behavior==='hunting-company'?'<p class="caravan-note">Reach a settlement to escape pursuit. Resting in the wilderness can be interrupted.</p>':'';
  const raidNotice=site.behavior==='raiding-caravan'?`<p class="band-activity ${caravan&&caravanContact(caravan)?'in-contact':''}">${raidPhase}</p>`:'';
  return `<div class="location-header hostile-location"><div class="eyebrow">${site.kind==='deserters'?'Contract · Elite faction deserters':roaming?esc(site.factionLabel||'Roaming brigands'):cleared?'Location cleared':esc(site.factionLabel||'Hostile camp')}</div><h2>${esc(site.name)}</h2><img class="settlement-portrait ${roaming?'band-portrait':''}" src="./assets/world/${roaming?({south:'figure_player_nomad',north:'figure_player_berserker',east:'figure_player_assassin',forest:'figure_player_ranger'}[site.factionId]||'figure_player_beggar'):'fortified_outpost_01'}.png" alt=""><p>${roaming&&site.difficulty===0?'<span class="small-band-rating">Small band · light equipment</span>':difficultyHTML(site.difficulty)}</p></div><p class="location-description">${cleared?`The brigands have been driven out. Raiders may return in ${Math.ceil(site.respawnHours/24)} days.`:esc(site.description || 'Brigands have made this place their home.')}</p>${roaming?`<p class="band-activity ${site.behavior==='hunting-company'||site.behavior==='raiding-caravan'?'is-threat':''}">${esc(activity)}</p>${raidNotice}${sanctuary}`:''}<div class="scouting-report"><h3>Scouting report</h3><p>${count} ${count===1?'brigand':'brigands'} · ${roaming&&site.difficulty===0?'An easier fight for a rested company':site.difficulty===1?'Thugs with simple weapons':site.difficulty===2?'Armed raiders':'Seasoned and armored raiders'}</p><p>${cleared?'No enemies remain.':esc(site.factionLabel||site.enemies.map(enemy=>enemy.name).join(', '))}</p>${site.veteranRank?`<p class="veteran-warning">Veteran rank ${site.veteranRank}: +${site.veteranRank*8} health, +${site.veteranRank*4} hit skill and +${site.veteranRank*2} defense per enemy. Reinforcements are included in the count above.</p>`:''}${scoutRoster}${site.enemies.some(e=>e.champion)?'<p class="champion-notice">★ Champion spotted: +40% health, +12 attack skill, +8 defense. Defeat them to recover their named trophy, even if its armor is destroyed. Escaping champions keep their gear.</p>':''}${mountNote}${!roaming&&!cleared&&famedChance?`<p class="famed-chance">Famed item chance: ${famedChance}%</p>`:''}</div><div class="stack">${cleared?'<button disabled>The camp is abandoned</button>':near?`<button class="primary" data-engage="${site.id}">Engage the enemy</button>`:`<button class="primary" ${['deserters','bounty'].includes(site.kind)?`data-quest-travel="${site.kind}" data-target-id="${site.id}"`:`data-camp-travel="${site.id}"`} ${pursuing?'disabled':''}>${pursuing?'Pursuing the band…':roaming?'Pursue this band':'Approach the camp'}</button>`}<button data-action="company">Inspect your company</button><button data-action="camp">Make camp · 6h</button><button data-action="nearest-town">Select nearest settlement</button></div><p class="battle-warning">${roaming?'Earn experience and loot before taking on fortified camps. Rest between fights; even small bands can hurt wounded brothers.':'Fight small roaming bands to train and afford better equipment before an assault.'}</p>`;
}

export function huntContractHTML(state, contract) {
  const target=getContractTarget(state,contract), issuer=town(contract.from), completed=contractObjectiveComplete(state,contract);
  const site=contract.campId?getCampSites(state).find(entry=>entry.id===contract.campId):null;
  const title=contract.type==='bounty'?'Wanted champion':contract.type==='deserters'?'Hunt elite deserters':contract.type==='assault'?'Join a camp assault':contract.type==='rescue'?'Rescue a besieged caravan':'Drive off brigands';
  const objective=contract.type==='bounty'?'Defeat the wanted champion and seven elite retainers. Return for 1,000 crowns and unlock the Bounty Hunter retinue, which costs 5,000 crowns to hire. The defeated champion guarantees their named trophy.':contract.type==='deserters'?'Defeat eight elite faction deserters and return for payment. Hard difficulty. On completion, a 25% chance upgrades one non-named weapon, armor, helmet or shield equipped by your company to named quality.':contract.type==='assault'?'Three allied militia wait at the brigand camp. The assault begins when you arrive; defeat its defenders, then return for payment.':contract.type==='rescue'?'Reach the surrounded caravan. The battle begins when you arrive, with its three guards fighting beside you. Return for payment after the rescue.':'Destroy the brigand camp, then return to your employer.';
  const travelType=contract.type==='bounty'?'bounty':contract.type==='deserters'?'deserters':contract.type==='rescue'?'rescue':'camp';
  return `<div class="contract-card"><div class="eyebrow">Contract · ${title}</div><h3>${esc(target?.name || site?.name || (contract.type==='rescue'?'Besieged caravan':'Brigand camp'))}</h3><p>${completed?`Objective complete. Return to ${esc(issuer.name)} for payment.`:objective}</p><div class="contract-reward">${contract.reward} crowns</div>${completed?`<button class="primary is-ready" data-travel="${issuer.id}">✓ Return to ${esc(issuer.name)}</button>`:target?`<button class="primary" data-quest-travel="${travelType}" data-target-id="${esc(target.id)}">${contract.type==='deserters'?'Confront the deserters':contract.type==='rescue'?'Join the rescue':contract.type==='assault'?'Join the assault':'Travel to the camp'}</button>`:'<button disabled>Objective unavailable</button>'}</div>`;
}

export function contractOffersHTML(state, offers) {
  return `<p class="contract-capacity">✉ Letter · ⚖ Merchant · ⚔ Combat <strong>${getActiveContracts(state).length} / 3</strong><small>One of each kind. Town boards refresh on day ${getContractBoardRefreshDay(state)}. Odran’s side quests stay independent.</small></p><div class="contract-offers bb-contracts">${offers.length?'':'<p class="empty-state">✓ This week’s work is taken. Check another town or return after the weekly refresh.</p>'}${offers.map(offer=>{
    const site=['hunt','assault'].includes(offer.type)?getCampSites(state).find(c=>c.id===offer.campId):null;
    const title=offer.type==='bounty'?'Hunt a wanted champion':offer.type==='deserters'?'Hunt elite deserters':offer.type==='hunt'?'Drive off brigands':offer.type==='assault'?'Join a camp assault':offer.type==='rescue'?'Rescue a besieged caravan':offer.type==='supply'?'Deliver supplies':'Deliver a package';
    const details=offer.type==='bounty'?'A named champion commands seven elite faction retainers. Hard fight; their named trophy is guaranteed if they are defeated. Return for 1,000 crowns and unlock the Bounty Hunter retinue (5,000 crowns to hire, permanent +5 percentage points to champion chance).':offer.type==='deserters'?'Eight elite faction soldiers have deserted with their regional armory. Hard fight; 25% chance on completion to upgrade one non-named weapon, armor, helmet or shield equipped by your company to named quality. Return here for payment.':offer.type==='hunt'?`Brigands are threatening our roads. Destroy their camp at ${site?.name || 'the marked location'}, then return here for your payment.`:offer.type==='assault'?`Three allied militia wait at ${site?.name || 'a brigand camp'}. The assault starts when you arrive. Defeat the defenders and return here for payment.`:offer.type==='rescue'?'Raiders have surrounded a caravan. The battle starts when you arrive, with its three guards fighting beside you. Return here for payment.':offer.type==='supply'?`Take ${offer.quantity} ${offer.goodId} to ${town(offer.to).name}. You must buy the goods yourself.`:`Carry these sealed dispatches safely to ${town(offer.to).name}.`;
    return `<article class="paper-card contract-scroll"><div class="contract-seal">${difficultyHTML(site?.difficulty||offer.difficulty||offer.rescueDifficulty||1)}</div><div class="eyebrow">${town(offer.from).name}</div><h3>${title}</h3><p>${esc(details)}</p>${getSettlementAccess(state,offer.to).servicesAvailable?'':'<p class="veteran-warning">Destination closed by undead. Liberate it before collecting payment.</p>'}<strong>${offer.reward} crowns on completion</strong><button class="primary" data-accept="${offer.id}" data-origin="${offer.from}" ${canAcceptContract(state,offer)?'':'disabled'} title="${canAcceptContract(state,offer)?'Accept contract':`Finish your current ${getContractCategory(offer)} contract first`}">${canAcceptContract(state,offer)?'Accept':'Slot occupied ·'} ${['hunt','assault','rescue','deserters','bounty'].includes(offer.type)?'combat contract':offer.type==='supply'?'supply order':'courier job'}</button></article>`;
  }).join('')}</div>`;
}

export function battleResultsHTML(state, keepLootIndices = []) {
  const battle=state.battle, victory=battle.status==='victory';
  const fallen=battle.units.filter(u=>u.side==='company'&&!u.ally&&!u.alive), survivors=battle.units.filter(u=>u.side==='company'&&!u.ally&&u.alive);
  const allies=battle.units.filter(u=>u.ally);
  const alliedRoster=allies.map(unit=>`<div class="battle-roster-row ${unit.alive?'':'fallen'}">${portraitHTML(unit,getEquipment(unit),54)}<div><strong>${esc(unit.name)}</strong><small>${unit.alive?'Survived the battle':'Fell in battle'} · Ally</small></div></div>`).join('');
  const loot={...battle.loot,gold:getBattleLootGold(state)}, share=getLootKeepQuote(state,keepLootIndices), selected=new Set(keepLootIndices);
  return `<section class="battle-results page"><div class="page-heading"><div><div class="eyebrow">AFTER THE BATTLE · ${battle.round} ROUNDS</div><h1>${victory?'Victory!':battle.status==='retreat'?'Retreat':'Defeat'}</h1><p>${victory?'The enemy is defeated. Count the spoils and tend to your company.':'Gather whoever remains and leave the battlefield.'}</p></div></div><div class="result-columns"><section class="result-panel"><h2>Your brothers</h2>${[...survivors,...fallen].map(unit=>`<div class="battle-roster-row ${unit.alive?'':'fallen'}">${portraitHTML(unit,getEquipment(unit),54)}<div><strong>${esc(unit.name)}</strong><small>${unit.alive?`${Math.ceil(unit.hp)} / ${unit.maxHp} hitpoints · ${getBattleExperience(state,unit.id)} experience`:'Killed in battle'}</small>${unit.alive?injuryPanelHTML(state,unit,{compact:true}):''}</div></div>`).join('')}${alliedRoster?`<h3>Allied fighters</h3>${alliedRoster}`:''}</section><section class="result-panel"><h2>${victory?'Spoils of war':'Losses'}</h2><div class="button-row loot-actions" aria-label="Loot actions">${victory&&loot.items?.length?`<button class="primary" data-action="keep-loot" ${selected.size?'':'disabled'}>Keep selected &amp; donate the rest</button><button data-action="donate-all">Donate all</button>`:""}<button class="primary" data-action="finish-battle">${victory?'Take all loot and continue':'Leave the battlefield'}</button></div><div class="loot-resources">${['gold','food','tools','medicine','ammo'].filter(key=>loot[key]).map(key=>`<div><strong>${loot[key]}</strong><span>${{gold:'Crowns',food:'Provisions',tools:'Tools',medicine:'Medicine',ammo:'Ammunition'}[key]}</span></div>`).join('')||'<p>No spoils recovered.</p>'}</div>${victory&&loot.items?.length?'<p class="loot-share-help">Tick the items you want to keep. Unticked items are donated for XP and morale. Kept items go into your stash where space allows; crowns and supplies are always collected.</p>':''}${getBattleChampionBounty(state)?`<p class="loot-share-help">Bounty Hunter: ${getBattleChampionBounty(state)} crowns included for defeated champions.</p>`:''}<div class="loot-items">${(loot.items||[]).map((id,index)=>{const lootItem=item(id),condition=loot.itemConditions?.[index],max=lootItem?.slot==='shield'?shieldMaximum(id):lootItem?.armor,damaged=Number.isFinite(condition)&&Number.isFinite(max)&&condition<max;return `<article class="loot-choice ${selected.has(index)?'is-keeping':''}"><button class="loot-item" data-inspect="${id}" data-item-source="loot" data-loot-index="${index}">${itemIcon(lootItem,'')}<span>${esc(lootItem?.name)}</span>${damaged?`<small class="loot-condition">${condition} / ${max} durability</small>`:''}</button>${victory?`<label class="loot-share-toggle"><input type="checkbox" data-keep-loot="${index}" ${selected.has(index)?'checked':''} aria-label="Keep ${esc(lootItem?.name)}, loot item ${index+1}"><span>Keep · ${share?.prices[index]??0} crowns</span></label>`:''}</article>`;}).join('')}</div>${victory&&loot.items?.length?`<section class="loot-share-preview" aria-live="polite" aria-atomic="true"><strong>${share?.selectedCount?`${selected.size} kept · ${share.selectedCount} donated · ${share.value} crowns`:'All items kept · no donation'}</strong><p>${share?.selectedCount?`${share.xpPool} XP pool · each of ${share.count} surviving brothers: +${share.xp} XP · up to +${share.morale} morale`:'No donation rewards. All loot items will be kept.'}</p><small>Sale values at ${esc(share?.townName)}. 5% of sale value becomes the XP pool; 25 crowns per morale. Split equally and rounded up. Maximum 500 XP and 15 morale per brother; morale cannot exceed 100.</small><small>Donate all includes items ticked to keep.</small></section>`:''}<p class="battle-warning">${fallen.length?`${fallen.length} ${fallen.length===1?'brother has':'brothers have'} fallen. ${victory?"Their equipment is recovered where stash space allows.":"Their worn equipment is lost."}`:'All brothers survived.'}</p><p>Armor and shield damage and wounds carry over to the world map. Make camp with tools and medicine to recover.</p></section></div></section>`;
}

export function gameOverHTML(state) {
  return `<section class="page ending-page"><div class="eyebrow">DAY ${state.day} · ${state.renown} RENOWN</div><h1>The company has fallen</h1><p>No brothers survived. This company's campaign is over.</p><div class="button-row"><button class="primary" data-action="new-game">Found a new company</button><button data-action="settings">Save / Menu</button></div></section>`;
}


export function discoveryNewsHTML(state) {
  const event=getDiscoveryEvent(state);
  return event?`<aside class="discovery-news" role="status"><div><strong>${esc(event.name)}</strong><span>Through day ${event.endDay} · ${event.remainingDays} ${event.remainingDays===1?'day':'days'} remaining</span><p>${esc(event.description)}</p></div><button data-action="retinue">Retinue &amp; rare finds</button></aside>`:'';
}
export function retinueHTML(state) {
  const cart=getCompanyCart(state),bounty=getRetinue(state),here=townAt(state);
  const available=!!here&&getSettlementAccess(state,here.id).servicesAvailable&&!state.battle&&!state.gameOver;
  const crowns=n=>n.toLocaleString('en-US');
  const card=({id,name,icon,detail,benefits,status,active,cost,action,label,locked=false})=>{
    const disabled=locked||!available||state.gold<cost;
    const reason=locked?'Complete a wanted contract':!available?'Visit an open settlement':state.gold<cost?`Need ${crowns(cost-state.gold)} more crowns`:'';
    return `<article class="retinue-choice ${active?'is-hired':''}" data-retinue-card="${id}"><div class="retinue-choice-heading"><img src="./assets/world/${icon}.png" alt="" loading="lazy"><div><h3 tabindex="-1">${name} ${companyHintHTML(`retinue-${id}`,name,detail)}</h3><span class="retinue-status">${active?'✓ ':''}${status}</span></div></div><div class="retinue-benefits">${benefits.map(value=>`<span>${value}</span>`).join('')}</div>${action?`<button class="${active?'':'primary'}" ${action} ${disabled?'disabled':''}>${label} · ${crowns(cost)} crowns</button><small class="retinue-guidance">${reason||'One-time purchase'}</small>`:'<span class="retinue-complete">Always active</span>'}</article>`;
  };
  const member=id=>{
    const definition=RETINUE_MEMBERS.find(m=>m.id===id),active=hasRetinue(state,id),upgrade=id==='scout'&&getScoutLevel(state)===1;
    return card({...definition,active,status:upgrade?'Upgrade available':active?'Hired':'Available',
      benefits:id==='scout'&&getScoutLevel(state)>0?[...definition.benefits,getScoutLevel(state)===2?'Enemy awareness −33%':'Upgrade: awareness −33%']:definition.benefits,
      cost:upgrade?10000:definition.cost,action:upgrade?'data-action="upgrade-scout"':active?'':`data-hire-retinue="${id}"`,label:upgrade?'Upgrade Scout':'Hire'});
  };
  const transport=card({id:'cart',name:cart.level===2?'Upgraded cart':'Company cart',icon:'trade_cart',active:cart.level>0,
    status:cart.level===2?'Fully upgraded':cart.level===1?'Upgrade available':'Available',cost:cart.cost,
    benefits:cart.level===2?[`Stash ${cart.stashCapacity}`,`Cargo ${cart.cargoCapacity}`,'No speed penalty']:[`Next stash ${crowns(cart.stashCapacity/(cart.level+1)*(cart.level+2))}`,`Next cargo ${cart.cargoCapacity/(cart.level+1)*(cart.level+2)}`,cart.level===0?'Movement −5%':'Remove speed penalty'],
    detail:'Buy for 7,500 crowns to double the original stash and cargo capacity, with a 5% movement penalty. Upgrade once for 15,000 crowns to triple the original capacities and remove the penalty.',
    action:cart.level<2?'data-action="buy-company-cart"':'',label:cart.level?'Upgrade cart':'Buy cart'});
  const tracker=card({id:'bounty',name:'Bounty Hunter',icon:'figure_player_ranger',active:bounty.hired,status:bounty.hired?'Bounty Hunter hired':bounty.unlocked?'Available':'Locked',
    cost:bounty.cost,benefits:['Champion chance +5 points',`${bounty.championBounty} crowns per champion`],locked:!bounty.unlocked,
    detail:'Complete a wanted champion contract and return to its issuer to unlock this hire. Permanently adds 5 percentage points to champion encounter chance and pays 300 crowns per defeated champion when collecting victory spoils. Escaped champions pay nothing. No wage, food upkeep or formation slot.',
    action:bounty.hired?'':'data-action="hire-bounty-hunter"',label:'Hire'});
  const count=RETINUE_MEMBERS.filter(m=>hasRetinue(state,m.id)).length+(bounty.hired?1:0);
  return `<section class="retinue-dashboard"><div class="retinue-overview"><div><strong>${count} specialists hired</strong><small>One-time hires · Always active</small></div><strong>${crowns(state.gold)} crowns</strong>${companyHintHTML('retinue-support','Company support','Hire at an open settlement. Specialists do not occupy formation slots or consume wages or food. All hired benefits stack. Buy a cart separately for more storage.')}</div><section><h3 class="retinue-group-title">Travel &amp; supplies</h3><div class="retinue-grid">${transport}${member('scout')}${member('quartermaster')}</div></section><section><h3 class="retinue-group-title">Recovery &amp; training</h3><div class="retinue-grid">${member('surgeon')}${member('armorer')}${member('drillmaster')}</div></section><section><h3 class="retinue-group-title">Trade &amp; spoils</h3><div class="retinue-grid">${member('broker')}${member('scavenger')}${tracker}</div></section><div class="retinue-rare-guide"><span>★ Rare finds</span>${companyHintHTML('retinue-rare','Rare finds','Look for gold stars marking champions. Defeated champions always drop their equipped named gear; escaping champions keep it. World events can improve champion, named-item and rare mount discoveries. Encounter rolls stay fixed through retreats and reloads.')}</div></section>`;
}

export function companyAutomationHTML(state,compact=false) {
  const ammoDetail=`Buy ammunition at settlements until stores reach ${AUTO_AMMO_CAP}. Normal prices; limited by available stock and crowns.`;
  if(compact)return `<fieldset class="company-automation company-automation-compact"><legend>Preparation</legend>${[['buyAmmo','Auto-buy ammunition',ammoDetail],['equipBandages','Auto-equip bandages','Best tiers from the stash first; fills or upgrades one medical slot per brother. Preserves non-medical accessories.']].map(([key,label,detail])=>`<div class="company-preparation-control"><label><input type="checkbox" data-company-automation="${key}" ${state.automation?.[key]?'checked':''} ${state.battle||state.gameOver?'disabled':''}><span>${label}</span></label>${companyHintHTML(`preparation-${key}`,label,detail)}</div>`).join('')}</fieldset>`;
  return `<fieldset class="company-automation"><legend>Company preparation</legend><label><input type="checkbox" data-company-automation="buyAmmo" ${state.automation?.buyAmmo?'checked':''} ${state.battle||state.gameOver?'disabled':''}><span>Auto-buy ammunition<small>${ammoDetail}</small></span></label><label><input type="checkbox" data-company-automation="equipBandages" ${state.automation?.equipBandages?'checked':''} ${state.battle||state.gameOver?'disabled':''}><span>Auto-equip bandages<small>Best tiers from the stash first; fills or upgrades one medical slot per brother. Preserves non-medical accessories.</small></span></label></fieldset>`;
}
